import random
random.seed(1)
fails = []
for trial in range(500):
    n = random.randint(1, 12)
    items = random.sample('abcdefghijklmn', n)
    L = list(items)
    s = IndexedSet(items)
    ok = True
    for step in range(40):
        if not ok: break
        op = random.choice(['pop_i','remove','discard','add','index','slice','len','iter_vs','getitem','index_err'])
        a = random.randint(-15, 15)
        try:
            if op == 'pop_i':
                if not L: continue
                if not (-len(L) <= a < len(L)):
                    try:
                        s.pop(a); fails.append(('pop_no_raise', a, trial)); ok=False
                    except IndexError: pass
                else:
                    got = s.pop(a)
                    if got != L[a]: fails.append(('pop_wrong', a, got, L[a], trial)); ok=False
                    else: L.pop(a)
            elif op == 'remove':
                if not L: continue
                x = random.choice(L); s.remove(x); L.remove(x)
            elif op == 'discard':
                x = random.choice(items); s.discard(x)
                if x in L: L.remove(x)
            elif op == 'add':
                x = random.choice(items)
                if x not in L: s.add(x); L.append(x)
            elif op == 'index':
                if not L: continue
                x = random.choice(items)
                if x in L:
                    if s.index(x) != L.index(x): fails.append(('index', x, trial)); ok=False
                else:
                    try: s.index(x); fails.append(('index_no_raise', x, trial)); ok=False
                    except ValueError: pass
            elif op == 'slice':
                a1 = random.randint(-15,15); b1 = random.randint(-15,15); c1 = random.choice([None,1,2,3,-1,-2,-4])
                sl = slice(a1,b1,c1); fs = list(s[sl])
                if c1 is None or c1 > 0:
                    if fs != L[sl]: fails.append(('fwd_slice', (a1,b1,c1), fs, L[sl], trial)); ok=False
                else:
                    fresh = IndexedSet(s)
                    if fs != list(fresh[sl]): fails.append(('neg_slice', (a1,b1,c1), fs, list(fresh[sl]), trial)); ok=False
            elif op == 'len':
                if len(s) != len(L): fails.append(('len', len(s), len(L), trial)); ok=False
            elif op == 'iter_vs':
                if list(s) != L: fails.append(('iter', list(s), L, trial)); ok=False
            elif op == 'getitem':
                if not L: continue
                if not (-len(L) <= a < len(L)):
                    try: s[a]; fails.append(('get_no_raise', a, trial)); ok=False
                    except IndexError: pass
                elif s[a] != L[a]: fails.append(('get', a, s[a], L[a], trial)); ok=False
            elif op == 'index_err':
                if not L: continue
                try:
                    s[random.choice(items)]  # just exercise
                except IndexError: pass
        except IndexError: fails.append(('unexpected_IndexError', op, a, trial)); ok=False
        except ValueError as e: fails.append(('unexpected_ValueError', op, str(e), trial)); ok=False
        except KeyError as e: fails.append(('unexpected_KeyError', op, str(e), trial)); ok=False
print('failures:', len(fails))
for f in fails[:20]: print(f)
