import sys, itertools
sys.path.insert(0, '.')
from more_itertools import always_iterable

def old_value_chain(*args):
    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            yield from value
        except TypeError:
            yield value

def new_value_chain(*args):
    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            iterator = iter(value)
        except TypeError:
            yield value
            continue
        yield from iterator

class Plain: pass
class Seq:
    def __getitem__(self, i):
        if i < 3: return i*10
        raise IndexError
class SeqBad:
    def __getitem__(self, key): raise TypeError('no key 0')
class SeqMid:
    def __getitem__(self, i):
        if i < 2: return i
        raise TypeError('bad at 2')
class BrokenIter:
    def __iter__(self): raise TypeError('boom __iter__')
class NonIterReturn:
    def __iter__(self): return 42
class GenIter:
    def __iter__(self):
        yield 1
        raise TypeError('gen __iter__')
def gen_first(): raise TypeError('first'); yield
def gen_mid(): yield 1; yield 2; raise TypeError('mid')
class RaisingAfter:
    def __iter__(self): return self
    def __next__(self): return 5  # never raises; but class below does
class IterRaiser:
    def __iter__(self): return self
    def __init__(self): self.n = 0
    def __next__(self):
        self.n += 1
        if self.n > 2: raise TypeError('next fail')
        return self.n
def map_bad(): return map(abs, [-1, 2, 'x'])

cases = {
    'int': 1, 'None': None, 'plain': Plain(), 'float': 2.5,
    'str': 'ab', 'bytes': b'cd', 'bytearray': bytearray(b'cd'),
    'list': [1,2], 'dict': {'k':1}, 'set': {1}, 'range': range(3),
    'Seq-getitem': Seq(), 'SeqBad(TypeError@0)': SeqBad(),
    'SeqMid(TypeError@2)': SeqMid(), 'BrokenIter': BrokenIter(),
    'NonIterReturn': NonIterReturn(), 'GenIter-yields-then-TE': GenIter(),
    'gen-first-TE': gen_first(), 'gen-mid-TE': gen_mid(),
    'map-bad': map_bad(), 'IterRaiser-after-2': IterRaiser(),
    'exhausted': iter([]),
}
def run(fn, v):
    try:
        out = []
        for x in fn(v): out.append(x)
        return ('yield', out)
    except TypeError as e:
        return ('TypeError', str(e))

print(f"{'case':26} {'old':40} {'new':40} {'always_iterable'}")
for name, v in cases.items():
    # fresh copies for one-shot items
    import copy
    def fresh(v):
        try: return copy.deepcopy(v)
        except Exception: return v
    o = run(old_value_chain, fresh(v))
    n = run(new_value_chain, fresh(v))
    a = run(lambda x: always_iterable(x), fresh(v))
    mark = '   <== DIFF' if o != n else ''
    def fmt(r):
        if r[0]=='yield':
            s = str(r[1])
