{"intent": "Test edge cases around the fix", "command": "cd work/repo && python3 -c "
from boltons.dictutils import OrderedMultiDict as OMD

# Test: values are equal, keys are equal, should return True
omd = OMD([('a', 1), ('b', 2)])
d = {'a': 1, 'b': 2}
print('Equal test:', omd == d)

# Test: values differ
d2 = {'a': 1, 'b': 3}
print('Value mismatch:', omd == d2)

# Test: missing key in dict
d3 = {'a': 1, 'c': 3}
print('Missing key:', omd == d3)

# Test: dict has same len but different keys
d4 = {'x': 1, 'y': 2}
print('Different keys same len:', omd == d4)

# Test: OMD has duplicate keys
omd2 = OMD([('a', 1), ('a', 2)])
d5 = {'a': 2}
print('OMD duplicate keys vs dict:', omd2 == d5)

# Test: dict with same keys, OMD has more values (duplicate keys)
d6 = {'a': 1}
print('Dict vs OMD with duplicates:', d6 == omd2)
""}

