# Verify invariant: item_index_map[item] always points at item_list[idx] == item (no drift)
def check(s, ctx):
    for item, i in s.item_index_map.items():
        if i >= len(s.item_list) or s.item_list[i] is not item or s.item_list[i] is _MISSING:
            return ('invariant', ctx, item, i, s.item_list)
    # dead intervals cover exactly MISSING slots
    miss = [i for i, v in enumerate(s.item_list) if v is _MISSING]
    cov = []
    for a, b in s.dead_indices:
        cov += list(range(a, b))
    if sorted(cov) != miss:
        return ('dead', ctx, miss, s.dead_indices)
    # _get_real_index(_get_apparent_index(i)) == i for all apparent i
    for i in range(len(s)):
        if s._get_real_index(i) >= len(s.item_list):
            return ('real', ctx, i)
    return None

