    def _cmp_numeric_str(cls, a: str, b: str) -> int:
        """
        Compare two ASCII all-digit prerelease identifiers as integers.

        This is equivalent to ``_cmp(int(a), int(b))`` but never calls
        :func:`int` on the strings: since Python 3.11 ``int()`` refuses
