print('1023949 gnu ->', repr(naturalsize(1023949, gnu=True)))
print('1048575 gnu ->', repr(naturalsize(1048575, gnu=True)))
print('report cases:')
for c in [(999_960,), (999_980_000,), (1024**3-1,), (999_960, False, True)]:
    print(' ', c, repr(naturalsize(*c)))
