{"intent": "Rigorous digit-count validation", "command": "cd work/repo && python3 - <<'PY'
import sys, re, random, math
sys.path.insert(0,"src")
import humanize

def count_sig_dec(s):
    """Count significant digits in the numeric portion of metric() output."""
    s = s.split(" x 10")[0]           # strip scientific suffix if present
    s = s.lstrip("-").strip()          # strip sign
    s = s.split(" ")[-1] if " " in s and not s[0].isdigit()==False else s
    # remove unit prefix/suffix letters (k,M,G,...,m,mu,n,p,..., degree etc.)
    # numeric part is everything up to first non [0-9.]
    m = re.match(r"-?[0-9.]+", s)
    if not m: return 0
    num = m.group(0)
    if "." in num:
        intpart, frac = num.split(".")
    else:
        intpart, frac = num, ""
    digits = (intpart + frac)
    # ignore leading zeros (they're placeholders), ignore trailing zeros only
    # when there is no decimal point (integer rounding); with decimal, all shown matter
    stripped_leading = digits.lstrip("0")
    if not stripped_leading: return 1
    if "." in num:
        # decimal: trailing zeros are significant (they're precision digits)
        return len(stripped_leading)
    else:
        # integer: trailing zeros ambiguous; but precision contract counts them
        # as shown digits, so count all non-leading-zero digits
        return len(stripped_leading)

viol = []
random.seed(42)
vals = []
for e in range(-32, 33):
    for _ in range(500):
        vals.append(random.uniform(1, 1000) * 10.0**e)
    for extra in (0.9999, 0.99999, 9.9999, 9.99999, 9.999999):
        vals.append(extra * 10.0**e)

for v in vals:
    for prec in (3, 4, 5):
        out = humanize.metric(v, "", prec)
        if " x 10" in out:
            continue  # scientific fallback, precision means decimals there
        n = count_sig_dec(out)
        if n > prec:
            viol.append((v, prec, out, n))
print("total tested:", len(vals)*3, " violations:", len(viol))
for x in viol[:15]: print(x)

# also verify report examples exactly
for inp, want in [(9996,'10.0 k'),(99960,'100 k'),(9.9996,'10.0'),(10400,'10.4 k'),(104000,'104 k'),(999.8,'1.00 kW')]:
    unit = 'W' if isinstance(inp,tuple) else ''
    got = humanize.metric(*((inp,unit) if unit else (inp,)))
    print("REPORT", inp, "->", repr(got), "OK" if got==want else "FAIL want "+repr(want))
