from more_itertools import zip_broadcast

# A: one-shot iterator whose __iter__ returns self with side effects
class SelfIter:
    def __init__(self):
        self.opens = 0
        self.items = iter('xy')
    def __iter__(self):
        self.opens += 1
        if self.opens > 1: raise ValueError('opened twice')
        return self
    def __next__(self): return next(self.items)

s = SelfIter()
print('A', list(zip_broadcast(s, 0)), 'opens=', s.opens)

# A2: same object passed TWICE (zip parity check)
s2 = SelfIter()
try:
    print('A2', list(zip_broadcast(s2, s2, 0)), 'opens=', s2.opens)
except Exception as e: print('A2', type(e).__name__, e)
s3 = SelfIter()
try:
    print('A2zip', list(zip(s3, s3, [0,0])))
except Exception as e: print('A2zip', type(e).__name__, e)

# B: strict=True pulls one extra item from longer source (one-shot must tolerate? count them)
class Counting:
    def __init__(self, n): self.n = n; self.pulled = 0
    def __iter__(self): return self
    def __next__(self):
        if self.pulled >= self.n: raise StopIteration
        self.pulled += 1
        return self.pulled
c = Counting(3)
try: list(zip_broadcast(c, [1], 0, strict=True))
except ValueError as e: print('B ValueError:', e, 'pulled=', c.pulled)

# C: ValueError raised inside __next__ mid-stream (not converted)
class BoomMid:
    def __iter__(self): return self
    def __next__(self): raise ValueError('mid-boom')
try: print('C', list(zip_broadcast(BoomMid(), [1], 0)))
except ValueError as e: print('C ValueError', e)

# H: __iter__ ok but __next__ raises TypeError
class TNext:
    def __iter__(self): return self
    def __next__(self): raise TypeError('type in next')
try: print('H', list(zip_broadcast(TNext(), [1], 0)))
except TypeError as e: print('H TypeError', e)

# L: empty real iterable + strict, scalar_types=None
try: print('L', list(zip_broadcast([], 'ab', scalar_types=None, strict=True)))
except ValueError as e: print('L ValueError:', e)

# zip eagerness check (baseline parity question)
class BoomIter:
    def __iter__(self): raise RuntimeError('boom-iter')
try:
    z = zip(BoomIter(), [0]); print('I zip construct ok (lazy)')
except RuntimeError: print('I zip constructs eagerly')
try:
    z = zip([], BoomIter()); print('J zip([], boom) ->', list(z))
except RuntimeError as e: print('J eager open:', e)
try:
    print('K zip_broadcast([], boom) ->', list(zip_broadcast([], BoomIter(), 0)))
except RuntimeError as e: print('K zip_broadcast opens all eagerly:', e)
