from itertools import count

# --- BASELINE (upstream v11.1.0, verbatim except docstring) ---
def baseline(*objects, scalar_types=(str, bytes), strict=False):
    def is_scalar(obj):
        if scalar_types and isinstance(obj, scalar_types):
            return True
        try:
            iter(obj)
        except TypeError:
            return True
        else:
            return False
    size = len(objects)
    if not size:
        return
    new_item = [None] * size
    iterables, iterable_positions = [], []
    for i, obj in enumerate(objects):
        if is_scalar(obj):
            new_item[i] = obj
        else:
            iterables.append(iter(obj))
            iterable_positions.append(i)
    if not iterables:
        yield tuple(objects)
        return
    for item in zip(*iterables, strict=strict):
        for i, new_item[i] in zip(iterable_positions, item):
            pass
        yield tuple(new_item)

# --- FIXED (verbatim from repo) ---
def fixed(*objects, scalar_types=(str, bytes), strict=False):
    def to_iterator(obj):
        if scalar_types and isinstance(obj, scalar_types):
            return None
        try:
            return iter(obj)
        except TypeError:
            return None
    def delegating(iterator):
        while True:
            try:
                yield next(iterator)
            except StopIteration:
                return
    size = len(objects)
    if not size:
        return
    new_item = [None] * size
    iterables, iterable_positions = [], []
    for i, obj in enumerate(objects):
        iterator = to_iterator(obj)
        if iterator is None:
            new_item[i] = obj
        else:
            iterables.append(delegating(iterator))
            iterable_positions.append(i)
    if not iterables:
        yield tuple(objects)
        return
    for item in zip(*iterables, strict=strict):
        for i, new_item[i] in zip(iterable_positions, item):
            pass
        yield tuple(new_item)

class BoomIter:
    def __iter__(self): raise RuntimeError('boom-iter')
class BoomIterT:
    def __iter__(self): raise TypeError('boom-type-iter')
class BoomNext:
    def __iter__(self): return self
    def __next__(self): raise RuntimeError('boom-next')
class StopNext:
    def __iter__(self): return self
    def __next__(self): raise StopIteration
class StopInIter:
    def __iter__(self): raise StopIteration
class NonIterResult:
    def __iter__(self): return None
class LegacySeq:
    def __init__(self, xs): self.xs = xs
    def __getitem__(self, i):
        if i >= len(self.xs): raise IndexError
        return self.xs[i]

def run(fn, args, kw):
    try:
        return ('ok', list(fn(*args, **kw)))
    except Exception as e:
        return ('err', type(e).__name__, str(e))

cases = [
    ('basic', ([1,2,3], ['a','b','c'], '_'), {}),
    ('strict-eq', ([1], [1], 0), {'strict': True}),
    ('strict-ne', ([1,2,3], [1,2], 0), {'strict': True}),
    ('no-args', (), {}),
    ('all-scalar', (1, 2), {}),
    ('single-iter', ([1,2]), {}),
    ('dict', ([1,2], {1:'x'}, 0), {}),
    ('none-arg', ([1,2], None, 0), {}),
    ('str-default', ('ab', [1,2]), {}),
    ('str-none', ('ab', [1,2]), {'scalar_types': None}),
    ('strtype', ('ab', 0), {'scalar_types': str}),
    ('empty-tuple-st', ('ab', 0), {'scalar_types': ()}),
    ('int-st', ([1,2], 0), {'scalar_types': (str, int)}),
    ('none-st', ([1,2], 0), {'scalar_types': None}),
    ('dict-st', ({'a':'b'}, [1,2,3]), {'scalar_types': dict}),
    ('infinite', (count(), 'ab'), {'scalar_types': None}),
    ('infinite-strict', (count(), [1,2]), {'strict': True}),
    ('empty-real-strict', ([], 'ab'), {'scalar_types': None, 'strict': True}),
    ('boom-iter', (BoomIter(), 0), {}),
    ('boom-iter-t', (BoomIterT(), 0), {}),
    ('boom-next', (BoomNext(), [1,2], 0), {}),
    ('stop-next', (StopNext(), 0), {}),
    ('stop-next-strict', ([1,2,3], StopNext(), 0), {'strict': True}),
    ('stop-in-iter', (StopInIter(), 0), {}),
    ('noniter-result', (NonIterResult(), 0), {}),
    ('legacy-seq', (LegacySeq('xy'), 0), {}),
    ('gen-arg', (iter([1,2,3]), 0), {}),
    ('mixed-order', (0, [1,2], 'x', {1:2}), {}),
    ('strict-empty-both', ([], []), {'strict': True}),
    ('scalar-strict', (1, 2), {'strict': True}),
]

diffs = 0
for name, args, kw in cases:
    r1 = run(baseline, args, kw)
    r2 = run(fixed, args, kw)
    same = (r1 == r2)
    if not same:
        diffs += 1
        print('DIFF', name)
        print('   baseline:', r1)
        print('   fixed   :', r2)
print('done, diffs =', diffs)
PYEOF
echo shell=$?"}

