// Reconstruct ORIGINAL identifier-handling logic on top of the same inc steps
function origInc(version, id, idBase) {
  const base = Number(idBase) ? 1 : 0
  const sv = new SemVer(version)
  // replicate inc('pre') steps exactly as in source
  if (sv.prerelease.length === 0) {
    sv.prerelease = [base]
  } else {
    let i = sv.prerelease.length
    while (--i >= 0) {
      if (typeof sv.prerelease[i] === 'number') { sv.prerelease[i]++; i = -2 }
    }
    if (i === -1) {
      if (id === sv.prerelease.join('.') && idBase === false) throw new Error('x')
      sv.prerelease.push(base)
    }
  }
  if (id) {
    let prerelease = [id, base]
    if (idBase === false) prerelease = [id]
    // ORIGINAL comparison
    const keep = compareIdentifiers(sv.prerelease[0], id) === 0 && !isNaN(sv.prerelease[1])
    if (!keep) sv.prerelease = prerelease
  }
  sv.raw = sv.format()
  return sv.version
}

