import json, re
old = json.load(open("diffchk/old.json"))
new = json.load(open("diffchk/new.json"))
buckets = {"limit_clean": [], "limit_leadingzero": [], "other": []}
nonlimit_old = []
for k in old:
    o, n = old[k], new[k]
    if o[0]=="e" and n[0]=="v":
        a, b = json.loads(k)
        if not o[2].startswith("Exceeds the limit"):
            nonlimit_old.append((k, o, n)); continue
        # find whether the huge digit identifier (the one old failed on) has a leading zero
        # old converts a_parts first then b_parts; failing operand = first with digit-run > 4300
        def first_id(parts):
            for p in parts:
                for ident in p.split("."):
                    if ident.isdigit() and len(ident) > 4300:
                        return ident
            return None
        ident = first_id([a or "", b or ""])
        if ident and ident.startswith("0"):
            buckets["limit_leadingzero"].append((a, b, n[1]))
        else:
            buckets["limit_clean"].append((a, b, n[1]))
